// src/pages/LoginPage.js

import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom'; // 페이지 이동을 위해 useNavigate 추가
import axios from 'axios'; // API 호출을 위해 axios 추가
import '../LoginPage.css';

function LoginPage() {
  const [id, setId] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState(''); // 에러 메시지 상태
  const navigate = useNavigate(); // 페이지 이동 함수

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(''); // 이전 에러 메시지 초기화

    if (!id || !password) {
      alert('ID와 비밀번호를 모두 입력해주세요.');
      return;
    }

    try {
      // ⭐️ 서버에 로그인 요청을 보냅니다.
      const response = await axios.post('http://localhost:4000/api/login', {
        username: id,
        password: password,
      });

      // ⭐️ 로그인 성공 시 서버로부터 받은 토큰을 localStorage에 저장합니다.
      const { token, user } = response.data;
      localStorage.setItem('token', token);
      localStorage.setItem('user', JSON.stringify(user));

      alert('로그인에 성공했습니다!');
      navigate('/'); // 로그인 성공 후 홈 페이지로 이동

    } catch (err) {
      // ⭐️ 로그인 실패 시 서버로부터 받은 에러 메시지를 표시합니다.
      const errorMessage = err.response?.data?.message || '로그인 중 오류가 발생했습니다.';
      setError(errorMessage);
      console.error('로그인 실패:', err);
    }
  };

  return (
    <div className="login-page-container">
      <h1 className="login-title">로그인</h1>
      
      <div className="login-form-card">
        <form onSubmit={handleSubmit}>
          {/* ... input-group들은 이전과 동일 ... */}
          
          {/* ⭐️ 에러 메시지를 표시하는 부분 추가 */}
          {error && <p className="error-message">{error}</p>}
          
          <button type="submit" className="login-button">
            로그인
          </button>
        </form>
        
        <Link to="/signup" className="signup-link">
          회원가입
        </Link>
      </div>
    </div>
  );
}

export default LoginPage;
